'use client';
import {useState, type FormEvent} from 'react';
export default function Login(){const[code,setCode]=useState('');const[busy,setBusy]=useState(false);const[error,setError]=useState('');async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const r=await fetch('/api/owner/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})});const d=await r.json() as {error?:string};if(!r.ok)throw new Error(d.error||'Unable to sign in.');window.location.assign('/admin')}catch(e){setError(e instanceof Error?e.message:'Unable to sign in.');setBusy(false)}}return <section className="section login-page"><span className="eyebrow">CLUB MANAGEMENT</span><h1>Owner login.</h1><p>Enter your administrator code to edit the calendar and club news.</p><form onSubmit={submit} style={{maxWidth:440,display:'grid',gap:16,marginTop:24}}><label htmlFor="owner-code">Administrator code</label><input id="owner-code" type="password" autoComplete="current-password" required maxLength={128} value={code} onChange={e=>setCode(e.target.value)} disabled={busy} style={{padding:'14px 16px',border:'1px solid #9daea6',borderRadius:8,fontSize:16}}/>{error&&<p className="error-box" role="alert">{error}</p>}<button className="button dark" disabled={busy}>{busy?'Checking…':'Enter editor mode'}</button></form><p className="fineprint">Your editor session lasts 8 hours. Keep your code private.</p></section>}

import {ownerUser} from '@/lib/owner';
import Admin from './workspace';
import Login from './login';
export const dynamic='force-dynamic';
export default async function Page(){const user=await ownerUser();return user?<Admin name={user.displayName}/>:<Login/>}

'use client';
import{useState}from'react';import{useClub}from'../use-club';import{Tabs,TabsList,TabsTrigger,TabsContent}from'@/components/ui/tabs';import{Select,SelectTrigger,SelectValue,SelectContent,SelectItem}from'@/components/ui/select';import{Checkbox}from'@/components/ui/checkbox';import{AlertDialog,AlertDialogContent,AlertDialogTitle,AlertDialogDescription,AlertDialogCancel}from'@/components/ui/alert-dialog';import{dateLabel,timeLabel,today}from'@/lib/club-types';
const newEvent=()=>({title:'',date:today(),start:'19:00',end:'21:00',location:'',description:'',category:'Open gym',cancelled:0,repeat:1});
const newPost=()=>({title:'',body:'',date:today(),status:'draft',pinned:0});
function Choice({value,onChange,options}:{value:string;onChange:(v:string)=>void;options:string[]}){return <Select value={value} onValueChange={onChange}><SelectTrigger className="form-select"><SelectValue/></SelectTrigger><SelectContent>{options.map(v=><SelectItem value={v} key={v}>{v}</SelectItem>)}</SelectContent></Select>}
export default function Admin({name}:{name:string}){const{events,posts,loading,error,load}=useClub(true);const[kind,setKind]=useState('events');const[edit,setEdit]=useState<any>(null);const[form,setForm]=useState<any>(null);const[saving,setSaving]=useState(false);const[message,setMessage]=useState('');const[saveError,setSaveError]=useState('');const[deleting,setDeleting]=useState<any>(null);const[preview,setPreview]=useState(false);const[dirty,setDirty]=useState(false);const[discard,setDiscard]=useState(false);const[queued,setQueued]=useState<(()=>void)|null>(null);
function guard(action:()=>void){if(dirty){setQueued(()=>action);setDiscard(true)}else action()}
function open(row:any=null,k=kind){guard(()=>{setKind(k);setEdit(row);setForm(row?{...row,repeat:1}:k==='events'?newEvent():newPost());setSaveError('');setMessage('');setPreview(false);setDirty(false)})}
function change(key:string,value:any){setForm({...form,[key]:value});setDirty(true)}
async function write(op:string,row:any=edit){setSaving(true);setSaveError('');setMessage('');try{const r=await fetch('/api/club',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,op,id:row?.id,version:row?.version,data:form})});const d:any=await r.json();if(!r.ok)throw new Error(d.error);setMessage(op==='delete'?'Entry deleted.':kind==='posts'&&form.status==='draft'?'Draft saved. Only you can see it.':'Saved. Your changes are now visible on the club website.');setDirty(false);setForm(null);setEdit(null);setDeleting(null);await load()}catch(e){setSaveError(e instanceof Error?e.message:'Could not save. Please try again.')}finally{setSaving(false)}}
return <section className="section admin-page"><div className="admin-heading"><div><span className="eyebrow">OWNER WORKSPACE</span><h1>Your club, up to date.</h1><p>Welcome, {name}. Changes are saved online and shared across devices.</p></div><form action="/api/owner/logout" method="post"><button className="outline-button" type="submit">Sign out</button></form></div><div className="admin-summary"><div><strong>{events.length}</strong><span>Calendar entries</span></div><div><strong>{posts.filter(p=>p.status==='published').length}</strong><span>Published updates</span></div><div><strong>{posts.filter(p=>p.status==='draft').length}</strong><span>Drafts</span></div></div>{message&&<p className="success-box" role="status">{message}</p>}<Tabs value={kind} onValueChange={v=>guard(()=>{setKind(v);setForm(null);setEdit(null);setDirty(false);setSaveError('')})}><TabsList className="admin-tabs"><TabsTrigger value="events">Calendar</TabsTrigger><TabsTrigger value="posts">News & updates</TabsTrigger></TabsList>{['events','posts'].map(k=><TabsContent value={k} key={k}><div className="admin-toolbar"><div><h2>{k==='events'?'Manage calendar':'Manage announcements'}</h2><p>{k==='events'?'Add a session, update a location, or mark a cancellation. All times are Eastern.':'News is separate from the Calendar. Edit an imported announcement below, or write a new update.'}</p></div><div className="toolbar-actions"><a href={k==='events'?'/calendar':'/news'} target="_blank" rel="noopener" className="outline-button">View page</a><button className="button dark" disabled={saving} onClick={()=>open(null,k)}>{k==='events'?'+ Add event':'+ Write update'}</button></div></div></TabsContent>)}</Tabs>
{form&&<section className="editor-panel"><div className="editor-heading"><h3>{edit?'Edit':'New'} {kind==='events'?'event':'update'}</h3><button className="outline-button" disabled={saving} onClick={()=>guard(()=>{setForm(null);setDirty(false)})}>Close editor</button></div><form onSubmit={e=>{e.preventDefault();write(edit?'update':'create')}}><div className="editor-grid"><label className="full-field">Title<input required maxLength={kind==='events'?120:180} value={form.title} onChange={e=>change('title',e.target.value)} placeholder={kind==='events'?'Sunday open gym':'A new update for the club'}/></label><label>Date<input type="date" required value={form.date} onChange={e=>change('date',e.target.value)}/></label>{kind==='events'?<><label>Session type<Choice value={form.category} onChange={v=>change('category',v)} options={['Open gym','Group training','Private coaching','Tournament','Closure']}/></label><label>Start time (Eastern)<input required type="time" value={form.start} onChange={e=>change('start',e.target.value)}/></label><label>End time (Eastern)<input required type="time" value={form.end} onChange={e=>change('end',e.target.value)}/></label><label className="full-field">Location<input required maxLength={200} value={form.location} onChange={e=>change('location',e.target.value)} placeholder="School or venue name and address"/></label><label className="full-field">Details<textarea rows={4} maxLength={5000} value={form.description} onChange={e=>change('description',e.target.value)} placeholder="Fees, equipment, arrival instructions…"/></label>{!edit&&<label>Create weekly sessions<input type="number" min={1} max={12} value={form.repeat} onChange={e=>change('repeat',Number(e.target.value))}/><small>1 = this date only. Up to 12 weekly dates, each editable separately.</small></label>}<label className="check-label"><Checkbox checked={!!form.cancelled} onCheckedChange={v=>change('cancelled',v?1:0)}/>Mark as cancelled</label></>:<><label>Visibility<Choice value={form.status} onChange={v=>change('status',v)} options={['draft','published']}/></label><label className="full-field">Your update<textarea rows={12} required maxLength={20000} value={form.body} onChange={e=>change('body',e.target.value)} placeholder="Write your announcement here…"/><small>Line breaks are preserved. The date is a display date; publishing makes the update visible immediately.</small></label><label className="check-label"><Checkbox checked={!!form.pinned} onCheckedChange={v=>change('pinned',v?1:0)}/>Pin to the top of the news page</label></>}</div>{saveError&&<p className="error-box" role="alert">{saveError}</p>}<div className="editor-actions"><button type="submit" className="button dark" disabled={saving}>{saving?'Saving…':kind==='events'?'Save event':form.status==='draft'?'Save draft':'Publish update'}</button>{kind==='posts'&&<button type="button" className="outline-button" onClick={()=>setPreview(!preview)}>{preview?'Hide preview':'Preview update'}</button>}<span className="fineprint">{dirty?'Unsaved changes':''}</span></div>{preview&&<article className="news-article editor-preview"><span className="eyebrow">PREVIEW</span><h2>{form.title||'Your title'}</h2><p className="preserve-lines">{form.body||'Your announcement will appear here.'}</p></article>}</form></section>}
{error?<div role="alert" className="error-box">{error}<button onClick={load}>Reload entries</button></div>:loading?<p role="status">Loading your entries…</p>:<div className="admin-entries">{(kind==='events'?events:posts).length===0?<div className="empty-state"><h3>{kind==='events'?'Your calendar starts here.':'Your next announcement starts here.'}</h3><p>{kind==='events'?'Add the first confirmed session. Old schedules have not been carried over.':'Write an update and save a draft or publish it immediately.'}</p><button className="button dark" onClick={()=>open()}>{kind==='events'?'Add first event':'Write first update'}</button></div>:(kind==='events'?events:posts).map((row:any)=><article className="admin-row" key={row.id}><div><div className="row-meta">{dateLabel(row.date)} {row.id.startsWith('archive-')&&<span className="tag">Imported news</span>} <span className="tag">{kind==='events'?(row.cancelled?'Cancelled':row.category):row.status}</span>{!!row.pinned&&<span className="tag">Pinned</span>}</div><h3>{row.title}</h3><p>{kind==='events'?`${timeLabel(row.start)} – ${timeLabel(row.end)} · ${row.location}`:row.body.slice(0,130)+(row.body.length>130?'…':'')}</p></div><div className="row-actions"><button disabled={saving} className="outline-button" onClick={()=>open(row)}>Edit</button><button disabled={saving} className="delete-button" onClick={()=>{setSaveError('');setDeleting(row)}}>Delete</button></div></article>)}</div>}
<AlertDialog open={!!deleting} onOpenChange={v=>!saving&&!v&&setDeleting(null)}><AlertDialogContent><AlertDialogTitle>Delete this {kind==='events'?'event':'update'}?</AlertDialogTitle><AlertDialogDescription>“{deleting?.title}” will be removed from the club website. This cannot be undone.</AlertDialogDescription>{saveError&&<p role="alert" className="error-box">{saveError}</p>}<div className="editor-actions"><AlertDialogCancel disabled={saving}>Keep it</AlertDialogCancel><button disabled={saving} className="button danger" onClick={()=>write('delete',deleting)}>{saving?'Deleting…':'Delete'}</button></div></AlertDialogContent></AlertDialog>
<AlertDialog open={discard} onOpenChange={setDiscard}><AlertDialogContent><AlertDialogTitle>Discard unsaved changes?</AlertDialogTitle><AlertDialogDescription>Your current edits have not been saved.</AlertDialogDescription><div className="editor-actions"><AlertDialogCancel>Keep editing</AlertDialogCancel><button className="button danger" onClick={()=>{setDiscard(false);setDirty(false);queued?.();setQueued(null)}}>Discard changes</button></div></AlertDialogContent></AlertDialog></section>}

import {ensureUserCalendar} from '@/lib/import-calendar';
import {ensureOriginalNews} from '@/lib/import-news';
import {clubDb} from '@/lib/club-db';import {ownerUser} from '@/lib/owner';import {eventSchema,postSchema} from '@/lib/club-validation';
export const dynamic='force-dynamic';
const reply=(body:unknown,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
export async function GET(request:Request){try{const admin=new URL(request.url).searchParams.get('admin')==='1';if(admin&&!await ownerUser())return reply({error:'Owner access required.'},403);await ensureOriginalNews();await ensureUserCalendar();const db=clubDb();const [events,posts]=await Promise.all([db.prepare('SELECT * FROM events ORDER BY date,start').all(),db.prepare(admin?'SELECT * FROM posts ORDER BY pinned DESC,date DESC':'SELECT * FROM posts WHERE status = ? ORDER BY pinned DESC,date DESC').bind(...(admin?[]:['published'])).all()]);return reply({events:events.results,posts:posts.results});}catch(e){console.error('Club load failed',e);return reply({error:'Could not load club information. Please try again.'},503)}}
export async function POST(request:Request){try{if(!await ownerUser())return reply({error:'Owner access required.'},403);if(request.headers.get('origin')!==new URL(request.url).origin)return reply({error:'Request origin not allowed.'},403);if(!request.headers.get('content-type')?.includes('application/json'))return reply({error:'JSON required.'},415);const raw=await request.text();if(raw.length>30000)return reply({error:'This entry is too long.'},413);let input;try{input=JSON.parse(raw)}catch{return reply({error:'Invalid request.'},400)}const{kind,op,id,version}=input;if(!['events','posts'].includes(kind)||!['create','update','delete'].includes(op))return reply({error:'Invalid action.'},400);if(op!=='create'&&(typeof id!=='string'||!Number.isInteger(version)))return reply({error:'Missing record version.'},400);const db=clubDb();if(op==='delete'){const r=await db.prepare(`DELETE FROM ${kind} WHERE id = ? AND version = ?`).bind(id,version).run();return r.meta.changes?reply({ok:true}):reply({error:'This entry changed. Reload before deleting.'},409)}const parsed=(kind==='events'?eventSchema:postSchema).safeParse(input.data);if(!parsed.success)return reply({error:parsed.error.issues.map(e=>e.message).join('. ')},400);const d=parsed.data as Record<string,any>;const cols=kind==='events'?['title','date','start','end','location','description','category','cancelled']:['title','body','date','status','pinned'];if(op==='update'){const r=await db.prepare(`UPDATE ${kind} SET ${cols.map(c=>c+' = ?').join(',')},version = version + 1 WHERE id = ? AND version = ?`).bind(...cols.map(c=>d[c]),id,version).run();return r.meta.changes?reply({ok:true}):reply({error:'This entry was changed in another window. Reload to get the latest version; your unsaved text is still here.'},409)}const count=kind==='events'?d.repeat:1;const ids=Array.from({length:count},()=>crypto.randomUUID());const statements=ids.map((newId,i)=>{const values={...d};if(kind==='events'){const date=new Date(d.date+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+7*i);values.date=date.toISOString().slice(0,10)}return db.prepare(`INSERT INTO ${kind} (id,${cols.join(',')}) VALUES (?,${cols.map(()=>'?').join(',')})`).bind(newId,...cols.map(c=>values[c]))});await db.batch(statements);return reply({ok:true,ids},201)}catch(e){console.error('Club save failed',e);return reply({error:'Could not save. Your changes are still in the form. Please try again.'},503)}}

import {env} from 'cloudflare:workers';
import {clubDb} from '@/lib/club-db';
import {digest,OWNER_COOKIE} from '@/lib/owner';
export const dynamic='force-dynamic';
const reply=(error:string,status:number)=>Response.json({error},{status,headers:{'Cache-Control':'no-store'}});
export async function POST(request:Request){
 if(request.headers.get('origin')!==new URL(request.url).origin)return reply('Request origin not allowed.',403);
 if(!request.headers.get('content-type')?.includes('application/json'))return reply('JSON required.',415);
 const expected=(env as unknown as {OWNER_CODE_SHA256?:string}).OWNER_CODE_SHA256;
 if(!expected)return reply('Owner login is not configured.',503);
 try{
  const db=clubDb(),now=Date.now();
  const key=await digest('owner-login:'+ (request.headers.get('cf-connecting-ip')||'unknown'));
  const attempt=await db.prepare('INSERT INTO login_attempts (key,count,reset_at) VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count = CASE WHEN reset_at <= ? THEN 1 ELSE count+1 END, reset_at = CASE WHEN reset_at <= ? THEN ? ELSE reset_at END RETURNING count').bind(key,now+15*60*1000,now,now,now+15*60*1000).first<{count:number}>();
  if(!attempt||attempt.count>8)return reply('Too many attempts. Please try again in 15 minutes.',429);
  const raw=await request.text();if(raw.length>1024)return reply('Invalid code.',400);
  let data;try{data=JSON.parse(raw)}catch{return reply('Invalid code.',400)}
  if(typeof data.code!=='string'||data.code.length>128)return reply('Invalid code.',400);
  const actual=await digest(data.code.trim());let diff=expected.length^actual.length;for(let i=0;i<actual.length;i++)diff|=actual.charCodeAt(i)^(expected.charCodeAt(i)||0);
  if(diff)return reply('Incorrect administrator code.',401);
  const token=Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');
  await db.batch([db.prepare('DELETE FROM owner_sessions WHERE expires_at <= ?').bind(now),db.prepare('DELETE FROM login_attempts WHERE reset_at <= ? OR key = ?').bind(now,key),db.prepare('INSERT INTO owner_sessions (token_hash,expires_at) VALUES (?,?)').bind(await digest(token),now+8*60*60*1000)]);
  return Response.json({ok:true},{headers:{'Cache-Control':'no-store','Set-Cookie':`${OWNER_COOKIE}=${token}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=28800`}});
 }catch{return reply('Login is temporarily unavailable. Please try again.',503)}
}

import {cookies} from 'next/headers';
import {clubDb} from '@/lib/club-db';
import {digest,OWNER_COOKIE} from '@/lib/owner';
export async function POST(request:Request){
 if(request.headers.get('origin')!==new URL(request.url).origin)return new Response('Forbidden',{status:403});
 const token=(await cookies()).get(OWNER_COOKIE)?.value;
 if(token)await clubDb().prepare('DELETE FROM owner_sessions WHERE token_hash = ?').bind(await digest(token)).run();
 return new Response(null,{status:303,headers:{Location:'/admin','Cache-Control':'no-store','Set-Cookie':`${OWNER_COOKIE}=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0`}});
}

'use client';
import{useState}from'react';import{useClub}from'../use-club';import{dateLabel,timeLabel,today}from'@/lib/club-types';import{Dialog,DialogContent,DialogTitle,DialogDescription}from'@/components/ui/dialog';import type{ClubEvent}from'@/lib/club-types';
export default function Calendar(){const{events,loading,error,load}=useClub();const[month,setMonth]=useState(()=>today().slice(0,7));const[selected,setSelected]=useState<ClubEvent|null>(null);const[y,m]=month.split('-').map(Number);const first=new Date(y,m-1,1).getDay();const days=new Date(y,m,0).getDate();const list=events.filter(e=>e.date.startsWith(month));const shift=(n:number)=>{const d=new Date(y,m-1+n,1);setMonth(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)};return <section className="section calendar-page"><div className="page-heading"><span className="eyebrow">LET’S PLAY</span><h1>Club calendar</h1><p>Open gym, training, and club events. All times are Eastern Time (Maryland).</p></div><div className="calendar-toolbar"><h2>{new Date(y,m-1,1).toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><div><button className="outline-button" onClick={()=>shift(-1)} aria-label="Previous month">Previous</button><button className="outline-button" onClick={()=>setMonth(today().slice(0,7))}>This month</button><button className="outline-button" onClick={()=>shift(1)} aria-label="Next month">Next</button></div></div>{loading?<p role="status">Loading the calendar…</p>:error?<div role="alert" className="error-box">{error}<button onClick={load}>Try again</button></div>:<><div className="calendar-grid">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=><div className="weekday" key={d}>{d}</div>)}{Array.from({length:first},(_,i)=><div className="calendar-cell blank" key={'b'+i}/>)}{Array.from({length:days},(_,i)=>{const date=`${month}-${String(i+1).padStart(2,'0')}`;return <div key={date} className={'calendar-cell '+(date===today()?'is-today':'')}><span className="day-number">{i+1}</span>{list.filter(e=>e.date===date).map(e=><button key={e.id} className={'calendar-event '+(e.cancelled?'cancelled':'')} onClick={()=>setSelected(e)}><span>{timeLabel(e.start)}</span><strong>{e.cancelled?'Cancelled · ':''}{e.title}</strong></button>)}</div>})}</div><div className="calendar-list"><h3>Sessions this month</h3>{!list.length?<div className="empty-state"><h3>No sessions posted for this month.</h3><p>Check another month, or contact the club for availability.</p><a href="tel:+12023908988">Call (202) 390-8988</a></div>:list.map(e=><button className="event-list-row" key={e.id} onClick={()=>setSelected(e)}><span>{dateLabel(e.date)}<small>{timeLabel(e.start)} – {timeLabel(e.end)}</small></span><strong>{e.title}<small>{e.location}</small></strong><span className="tag">{e.cancelled?'Cancelled':e.category}</span></button>)}</div></>}<Dialog open={!!selected} onOpenChange={v=>!v&&setSelected(null)}><DialogContent className="club-dialog"><DialogTitle>{selected?.title}</DialogTitle><DialogDescription>{selected&&dateLabel(selected.date)} · Eastern Time</DialogDescription>{selected&&<div><span className="tag">{selected.cancelled?'Cancelled':selected.category}</span><p>{timeLabel(selected.start)} – {timeLabel(selected.end)}<br/><strong>{selected.location}</strong></p><p className="preserve-lines">{selected.description}</p></div>}</DialogContent></Dialog></section>}

import { headers } from "next/headers";
import { redirect } from "next/navigation";

export type ChatGPTUser = {
  userId: string;
  displayName: string;
  email: string;
  fullName: string | null;
};

const USER_ID_HEADER = "oai-authenticated-user-id";
const USER_EMAIL_HEADER = "oai-authenticated-user-email";
const USER_FULL_NAME_HEADER = "oai-authenticated-user-full-name";
const USER_FULL_NAME_ENCODING_HEADER =
  "oai-authenticated-user-full-name-encoding";
const PERCENT_ENCODED_UTF8 = "percent-encoded-utf-8";
const SIGN_IN_PATH = "/signin-with-chatgpt";
const SIGN_OUT_PATH = "/signout-with-chatgpt";
const CALLBACK_PATH = "/callback";

export async function getChatGPTUser(): Promise<ChatGPTUser | null> {
  const requestHeaders = await headers();
  const userId = requestHeaders.get(USER_ID_HEADER);
  const email = requestHeaders.get(USER_EMAIL_HEADER);
  if (!userId || !email) return null;

  const encodedFullName = requestHeaders.get(USER_FULL_NAME_HEADER);
  const fullName =
    encodedFullName &&
    requestHeaders.get(USER_FULL_NAME_ENCODING_HEADER) === PERCENT_ENCODED_UTF8
      ? safeDecodeURIComponent(encodedFullName)
      : null;

  return {
    userId,
    displayName: fullName ?? email,
    email,
    fullName,
  };
}

export async function requireChatGPTUser(
  returnTo: string,
): Promise<ChatGPTUser> {
  const user = await getChatGPTUser();
  if (user) return user;

  redirect(chatGPTSignInPath(returnTo));
}

export function chatGPTSignInPath(returnTo: string): string {
  const safeReturnTo = safeRelativeReturnPath(returnTo);
  return `${SIGN_IN_PATH}?return_to=${encodeURIComponent(safeReturnTo)}`;
}

export function chatGPTSignOutPath(returnTo = "/"): string {
  const safeReturnTo = safeRelativeReturnPath(returnTo);
  return `${SIGN_OUT_PATH}?return_to=${encodeURIComponent(safeReturnTo)}`;
}

function safeRelativeReturnPath(value: string): string {
  if (!value.startsWith("/") || value.startsWith("//")) return "/";

  let url: URL;
  try {
    url = new URL(value, "https://app.local");
  } catch {
    return "/";
  }
  if (url.origin !== "https://app.local") return "/";
  if (isReservedAuthPath(url.pathname)) return "/";

  return `${url.pathname}${url.search}${url.hash}`;
}

function isReservedAuthPath(pathname: string): boolean {
  return (
    pathname === SIGN_IN_PATH ||
    pathname === SIGN_OUT_PATH ||
    pathname === CALLBACK_PATH
  );
}

function safeDecodeURIComponent(value: string): string | null {
  try {
    return decodeURIComponent(value);
  } catch {
    return null;
  }
}

