const results=[['2000','U.S. Adult Nationals','Singles','1st'],['1999','U.S. Adult Nationals','Singles, doubles, mixed doubles','1st in all three'],['1998','U.S. Adult Nationals','Singles, doubles, mixed doubles','1st in all three'],['1997','U.S. Adult Nationals','Doubles / singles','1st / 2nd'],['1996','U.S. Adult Nationals','Singles, mixed doubles / doubles','1st / 2nd'],['1999','Pan American Games · Winnipeg','Singles / mixed doubles','Gold / bronze'],['1999','U.S. Open · Orange County','Singles / mixed doubles','1st / 2nd'],['1987','World Junior Championships · Jakarta','Doubles','3rd'],['1987','All China Junior Nationals','Singles','2nd']];
