r email the club for current training details and to register your interest.</p><a className="button dark" href="tel:+12023908988">Call (202) 390-8988</a><a className="training-email" href="mailto:info@eastcoastbadmintonclub.com?subject=Training%20program%20inquiry">info@eastcoastbadmintonclub.com</a><a className="underlined" href="/calendar">See the current open gym calendar</a></div></section></>}

'use client';
import {useCallback,useEffect,useState} from 'react';import type{ClubEvent,Post}from '@/lib/club-types';
export function useClub(admin=false){const[data,setData]=useState<{events:ClubEvent[];posts:Post[]}>({events:[],posts:[]});const[loading,setLoading]=useState(true);const[error,setError]=useState('');const load=useCallback(async()=>{setError('');setLoading(true);try{const r=await fetch('/api/club'+(admin?'?admin=1':''),{cache:'no-store'});const d:any=await r.json();if(!r.ok)throw new Error(d.error);setData(d);return true}catch(e){setError(e instanceof Error?e.message:'Unable to load.');return false}finally{setLoading(false)}},[admin]);useEffect(()=>{load()},[load]);return{...data,loading,error,load}}

